import json

# Try: even columns get filled based on boundary, odd columns stay background (1)
# Boundary shifts left by 2 columns (1 regular col) per row

def funnel_grid(H=6, W=19, tl=9, tr=6):
    grid = [[0]*W for _ in range(H)]  # Initialize with background

    for r in range(H):
        # Compute effective boundary at row r
        # Start at 12 (column index where 13 even positions exist)
        # Shift left by r
        left_limit = 12 - r  # This might go negative

        for c in range(W):
            if c % 2 != 0:
                continue  # Odd cols = background we'll set later

            if c <= left_limit:
                grid[r][c] = tl
            else:
                grid[r][c] = tr

    # Set odd columns to background (1)
    for r in range(H):
        for c in range(W):
            if c % 2 != 0:
                grid[r][c] = 1

    return grid

grid = [grid[r] if r < len(grid) else [1]*19 for r in range(6)]
grid = funnel_grid()
print("Funnel with even-col filling:")
for row in grid:
    print(" ".join(map(str, row)))

print("\nSubmit:")
print(json.dumps({"action": "submit", "grid": grid}))

