# Try: corner spreading with NO parity constraint, just meet in middle boundary
# This is the simplest 4-corner meet-in-middle model

grid = []
for r in range(6):
    row = []
    for c in range(19):
        # Top half (r <= 2): meet at column 9
        # Bottom half (r > 2): meet at column 9
        # But with diagonal slant: column = 9 - r/2

        # Use integer division for diagonal movement
