import json

# Final attempt: closest-corner, keeping odd columns as 1

H, W = 6, 19
vals = [9, 6, 5, 7]
grid = [[1] * W for _ in range(H)]

for r in range(H):
    for c in range(W):
        d_tl = r + c
        d_tr = r + (W - 1 - c)
        d_bl = (H - 1 - r) + c
        d_br = (H - 1 - r) + (W - 1 - c)

        dists = [d_tl, d_tr, d_bl, d_br]
        min_d = min(dists)

        if dists[dists.index(min_d)] == d_tl:
            grid[r][c] = 9
        elif dists[dists.index(min_d)] == d_tr:
            grid[r][c] = 6
        elif dists[dists.index(min_d)] == d_bl:
            grid[r][c] = 5
        else:
            grid[r][c] = 7

# Now overwrite odd columns with 1
for r in range(H):
    for c in range(W):
        if c % 2 == 1:
            grid[r][c] = 1

print("Closest-corners, odd-columns-1:")
for row in grid:
    print(" ".join(map(str, row)))

print("\nSubmit:")
print(json.dumps({"action": "submit", "grid": grid}))

